mapper.select:
SELECT
    m.id, m.name, m.phone, m.gender, m.birthday, m.level_id, m.balance, m.points,
    m.source, m.status, m.store_id, s.name AS store_name, l.name AS level_name,
    m.remark, m.create_time
FROM salon_member m
LEFT JOIN salon_store s ON s.id = m.store_id AND s.deleted = 0
LEFT JOIN salon_member_level l ON l.id = m.level_id AND l.deleted = 0

    m.deleted = 0

        AND (
            m.name LIKE CONCAT('%', CAST(#{q.keywords} AS text), '%')
            OR m.phone LIKE CONCAT('%', CAST(#{q.keywords} AS text), '%')
            OR s.name LIKE CONCAT('%', CAST(#{q.keywords} AS text), '%')
        )


        AND m.status = #{q.status}


        AND m.tenant_id = #{q.tenantId}


        AND m.store_id = #{q.storeId}


        AND m.level_id = #{q.levelId}


        AND EXISTS (
            SELECT 1 FROM salon_member_tag_rel r
            WHERE r.member_id = m.id AND r.tag_id = #{q.tagId} AND r.deleted = 0
        )




                AND 1 = 0


                AND (


                            OR m.store_id IN

                                #{storeId}



                            OR m.create_by = #{q.permissionUserId}


                )




ORDER BY m.create_time DESC
